Ltac rgF_tail bd vd Rd Ed SOK n ps pd s4 d4 :=
  stepLD F_25930 D_25930 bd vd ltac:(addr_norm; rewrite ?Z.add_0_r; exact Rd) ltac:(exact Ed);
