(* [comment removed for export] *)
Lemma rg_Q2 : forall regs m (DX SX DW dy sy dwpl swpl datad datas : Z),
  (0 <= DX < 2 ^ 31)%Z -> (0 <= SX < 2 ^ 31)%Z -> (0 <= DW < 2 ^ 31)%Z -> (DX mod 32 <> 0)%Z ->
  getr regs 20 = Z_to_bv 64 (DX mod 32) -> getr regs 29 = Z_to_bv 64 (32 - DX mod 32) -> getr regs 30 = Z_to_bv 64 (SX mod 32) ->
  getr regs 31 = Z_to_bv 64 (32 - SX mod 32) -> getr regs 6 = Z_to_bv 64 DW -> getr regs 19 = Z_to_bv 64 DX -> getr regs 26 = Z_to_bv 64 SX ->
  getr regs 27 = Z_to_bv 64 dy -> getr regs 23 = Z_to_bv 64 sy -> getr regs 14 = Z_to_bv 64 dwpl -> getr regs 13 = Z_to_bv 64 swpl ->
  getr regs 5 = Z_to_bv 64 datad -> getr regs 22 = Z_to_bv 64 datas -> getr regs 8 = Z_to_bv 64 0x128b0 ->
  exists regs',
    msteps SEGS (mkst regs (0x23ecc : word) m rom) (mkst regs' (0x23f18 : word) m rom)
    /\ getr regs' 8 = Z_to_bv 64 (datad + 4 * (dy * dwpl) + 4 * (DX / 32)) /\ getr regs' 1 = Z_to_bv 64 (datas + 4 * (sy * swpl) + 4 * (SX / 32))
    /\ getr regs' 25 = Z_to_bv 64 (if g_f6 DX SX then 1 else 0) /\ getr regs' 24 = Z_to_bv 64 (if g_f7 SX DW then 1 else 0)
